var msg_payload = msg.payload;

if (msg_payload.scene_name) {
    var region_name = msg_payload.region_name;
    var timestamp = msg_payload.timestamp;
    var counts = msg_payload.counts;
    var count_keys = Object.keys(counts);

    count_keys.forEach(function (key) {
        var json_body = [
            { count: counts[key] + "i" },
            {
                location: msg_payload.scene_name || "Anthem",
                region: region_name,
                object: key
            }
        ];
        node.send({ payload: json_body, measurement: "region_obj_count_2", timestamp: timestamp });
    });

    var objects_exited = msg_payload.exited;
    var items_exited = objects_exited.length;
    if (items_exited > 0) {
        objects_exited.forEach(function (obj) {
            var json_body2 = [
                { dwell_time: parseFloat(obj.dwell.toFixed(2)) },
                {
                    location: msg_payload.scene_name || "Anthem",
                    region: region_name,
                    object: obj.object.category
                }
            ];
            node.send({ payload: json_body2, measurement: "region_obj_dwell_2", timestamp: timestamp });
        });
    }

    var pedestrian_noped_count = Number((counts || {}).pedestrian || 0);
    var vehicle_noped_count = Number((counts || {}).vehicle || 0);
    var jaywalking_detected = region_name === "NOPED" && pedestrian_noped_count > 0;
    var collision_count = jaywalking_detected ? vehicle_noped_count : 0;

    var collision_body = [
        {
            count: collision_count + "i",
            trigger: (collision_count > 0 ? 1 : 0) + "i"
        },
        {
            location: msg_payload.scene_name || "Anthem",
            region: "NOPED",
            object: "vehicle"
        }
    ];
    node.send({ payload: collision_body, measurement: "collision_events_2", timestamp: timestamp });
}
return null;

var msg_payload = msg.payload;

if (msg_payload.name === 'Intersection-Demo') {
    var timestamp = msg_payload.timestamp;
    // Handle pedestrian tracking data
    if (msg_payload.objects && Array.isArray(msg_payload.objects)) {
        msg_payload.objects.forEach(function (obj) {
            if (obj.category === "pedestrian" && ("lat_long_alt" in obj)) {
                // Calculate speed (velocity magnitude)
                var vel = obj.velocity || [0, 0, 0];
                var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1] + vel[2] * vel[2]);

                var json_body3 = [
                    {
                        pedid: obj.id,
                        latitude: obj.lat_long_alt ? obj.lat_long_alt[0] : 0,
                        longitude: obj.lat_long_alt ? obj.lat_long_alt[1] : 0,
                        heading: obj.heading || 0,
                        velocity: speed.toFixed(2)
                    },
                    {
                        location: msg_payload.name || msg_payload.scene_name || "Anthem"
                    }
                ];

                node.send({
                    payload: json_body3,
                    measurement: "pedestrian_loc",
                    timestamp: timestamp
                });
            }
        });
    }
}
return null;

var msg_payload = msg.payload;

var tripwire_name = msg_payload.tripwire_name;
var timestamp = msg_payload.timestamp;
var objects = msg_payload.objects || [];
var fs = global.get('fs');
var imgCache = flow.get('vehicleImageCache') || {};

var wrong_way_direction = {
    'NBLANE_START_TW': -1,
    'NBLANE_END_TW': -1,
    'SBLANE_START_TW': -1,
    'SBLANE_END_TW': -1,
    'EBLANE_START_TW': -1,
    'EBLANE_END_TW': -1,
    'WBLANE_START_TW': -1,
    'WBLANE_END_TW': -1
};

var bad_dir = wrong_way_direction[tripwire_name];
if (bad_dir === undefined) { return null; }

var lane = tripwire_name.replace('_START_TW', '').replace('_END_TW', '');

var ts = new Date();
try { ts = new Date(timestamp); } catch (e) {}
var dateStr = ts.toISOString().split("T")[0];
var timeStr = ts.toTimeString().split(" ")[0].replace(/:/g, "");

objects.forEach(function (obj) {
    if (obj.direction === bad_dir) {
        var vel = obj.velocity || [0, 0, 0];
        var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1]);

        if (speed < 0.5) { return; }

        // Analytics events do not carry images; use the ones cached from the scene controller output.
        var cached = imgCache[obj.id] || {};
        obj.image_b64 = obj.image_b64 || cached.image_b64;
        obj.frame_b64 = obj.frame_b64 || msg_payload.frame_b64 || cached.frame_b64;

        var imageUrl = "";
        var frameUrl = "";
        var baseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;

        if (obj.image_b64) {
            try {
                fs.mkdirSync(baseDir, { recursive: true });
                var imgName = `wrongway_${obj.id || 'unknown'}_${timeStr}.jpg`;
                fs.writeFileSync(`${baseDir}/${imgName}`, Buffer.from(obj.image_b64, "base64"));
                imageUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${imgName}`;
            } catch (err) {}
        }

        var f_b64 = obj.frame_b64 || msg_payload.frame_b64;
        if (f_b64) {
            try {
                fs.mkdirSync(baseDir, { recursive: true });
                var frameName = `wrongway_frame_${obj.id || 'unknown'}_${timeStr}.jpg`;
                fs.writeFileSync(`${baseDir}/${frameName}`, Buffer.from(f_b64, "base64"));
                frameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${frameName}`;
            } catch (err) {}
        }

        var json_body = [
            {
                object_id: String(obj.uuid || obj.global_id || obj.id || 'unknown'),
                heading: obj.heading || 0,
                speed: parseFloat(speed.toFixed(2)),
                wrong_way: 1,
                event_url: imageUrl,
                frame_url: frameUrl
            },
            {
                location: msg_payload.scene_name || 'Anthem',
                region: lane,
                object: obj.category || 'vehicle'
            }
        ];

        node.send({
            payload: json_body,
            measurement: 'wrong_way_alert',
            timestamp: timestamp
        });
    }
});

return null;

var msg_payload = msg.payload;

var REGION_CONFIG = {
    'NBLANE':  { stall_threshold_sec: 60 },
    'SBLANE':  { stall_threshold_sec: 60 },
    'EBLANE':  { stall_threshold_sec: 60 },
    'WBLANE':  { stall_threshold_sec: 60 },
    'NOPED':   { stall_threshold_sec: 20 },
    'INTERSECTION': { stall_threshold_sec: 15 }
};

var SPEED_THRESHOLD = 0.5;
var CLEANUP_TIMEOUT_SEC = 60;
var fs = global.get('fs');
var imgCache = flow.get('vehicleImageCache') || {};

var tracker = flow.get('stalledVehicleTracker') || {};

var timestamp    = msg_payload.timestamp;
var region_name  = msg_payload.region_name || msg_payload.scene_name;
var objects      = msg_payload.objects || [];

if (!REGION_CONFIG[region_name]) { return null; }

var threshold_sec = REGION_CONFIG[region_name].stall_threshold_sec;
var now_sec       = parseFloat(timestamp);

var ts = new Date();
try { ts = new Date(timestamp * 1000); } catch (e) {}
var dateStr = ts.toISOString().split("T")[0];
var timeStr = ts.toTimeString().split(" ")[0].replace(/:/g, "");

objects.forEach(function (obj) {
    if (obj.category !== 'vehicle') { return; }

    var id  = obj.id;
    var vel = obj.velocity || [0, 0, 0];
    var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1]);

    if (!tracker[id]) {
        tracker[id] = {
            firstStationarySec: speed < SPEED_THRESHOLD ? now_sec : null,
            lastSeenSec:        now_sec,
            region:             region_name,
            alertSent:          false,
            speed:              parseFloat(speed.toFixed(2))
        };
    } else {
        var rec = tracker[id];
        rec.lastSeenSec = now_sec;
        rec.speed       = parseFloat(speed.toFixed(2));

        if (speed >= SPEED_THRESHOLD) {
            rec.firstStationarySec = null;
            rec.alertSent          = false;
            rec.region             = region_name;
        } else {
            if (rec.firstStationarySec === null) {
                rec.firstStationarySec = now_sec;
            }

            var stalled_duration_sec = now_sec - rec.firstStationarySec;

            if (stalled_duration_sec >= threshold_sec && !rec.alertSent) {
                rec.alertSent = true;

                // Analytics events do not carry images; use the ones cached from the scene controller output.
                var cached = imgCache[id] || {};
                obj.image_b64 = obj.image_b64 || cached.image_b64;
                msg_payload.frame_b64 = msg_payload.frame_b64 || cached.frame_b64;

                var imageUrl = "";
                var frameUrl = "";
                var baseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;

                if (obj.image_b64) {
                    try {
                        fs.mkdirSync(baseDir, { recursive: true });
                        var imgName = `stalled_${id}_${timeStr}.jpg`;
                        fs.writeFileSync(`${baseDir}/${imgName}`, Buffer.from(obj.image_b64, "base64"));
                        imageUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${imgName}`;
                    } catch (err) {}
                }

                if (msg_payload.frame_b64) {
                    try {
                        fs.mkdirSync(baseDir, { recursive: true });
                        var frameName = `stalled_frame_${id}_${timeStr}.jpg`;
                        fs.writeFileSync(`${baseDir}/${frameName}`, Buffer.from(msg_payload.frame_b64, "base64"));
                        frameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${frameName}`;
                    } catch (err) {}
                }

                var json_body = [
                    {
                        stalled_duration: parseFloat(stalled_duration_sec.toFixed(2)),
                        speed:            rec.speed,
                        trigger:          1,
                        event_url:        imageUrl,
                        frame_url:        frameUrl
                    },
                    {
                        location:   msg_payload.scene_name || msg_payload.name || 'Anthem',
                        region:     region_name,
                        object:     'vehicle',
                        vehicle_id: String(id)
                    }
                ];
                node.send({
                    payload:     json_body,
                    measurement: 'stalled_vehicle_alert',
                    timestamp:   timestamp
                });
            }
        }
    }
});

Object.keys(tracker).forEach(function (id) {
    if ((now_sec - tracker[id].lastSeenSec) > CLEANUP_TIMEOUT_SEC) {
        delete tracker[id];
    }
});

flow.set('stalledVehicleTracker', tracker);
return null;

// === CONGESTION DETECTION LOGIC (Low average speed over n seconds) ===
var CONGESTION_CONFIG = {
    'NBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'SBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'EBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'WBLANE':       { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 },
    'INTERSECTION': { speed_threshold: 2.0, duration_sec: 10, min_vehicles: 3 }
};

var congTracker = flow.get('congestionTracker') || {};
var cfg = CONGESTION_CONFIG[region_name] || { speed_threshold: 3.0, duration_sec: 10, min_vehicles: 2 };

var regVehicles = [];
var congFrameB64 = null;

objects.forEach(function (o) {
    if (o.category === 'vehicle') {
        var v = o.velocity || [0, 0, 0];
        var s = Math.sqrt(v[0] * v[0] + v[1] * v[1]);
        regVehicles.push(s);

        if (!congFrameB64) {
            if (o.frame_b64) { congFrameB64 = o.frame_b64; }
            else if (msg_payload.frame_b64) { congFrameB64 = msg_payload.frame_b64; }
        }
    }
});

if (!congTracker[region_name]) {
    congTracker[region_name] = { firstLowSpeedSec: null, alertSent: false };
}
var cState = congTracker[region_name];

if (regVehicles.length >= cfg.min_vehicles) {
    var totSpeed = regVehicles.reduce(function(a, b) { return a + b; }, 0);
    var avgSpeed = totSpeed / regVehicles.length;

    if (avgSpeed < cfg.speed_threshold) {
        if (cState.firstLowSpeedSec === null) {
            cState.firstLowSpeedSec = now_sec;
        }
        var congDurationSec = now_sec - cState.firstLowSpeedSec;

        if (congDurationSec >= cfg.duration_sec && !cState.alertSent) {
            cState.alertSent = true;

            var congFrameUrl = "";
            if (congFrameB64) {
                try {
                    var cBaseDir = `/images_data/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}`;
                    fs.mkdirSync(cBaseDir, { recursive: true });
                    var cFrameName = `congestion_frame_${region_name}_${timeStr}.jpg`;
                    fs.writeFileSync(`${cBaseDir}/${cFrameName}`, Buffer.from(congFrameB64, "base64"));
                    congFrameUrl = `/images/vehicle-events/${dateStr}/${msg_payload.scene_name || 'Anthem'}/${cFrameName}`;
                } catch (err) {}
            }

            var congBody = [
                {
                    avg_speed:     parseFloat(avgSpeed.toFixed(2)),
                    dwell_time:    parseFloat(congDurationSec.toFixed(2)),
                    vehicle_count: regVehicles.length,
                    trigger:       1,
                    frame_url:     congFrameUrl
                },
                {
                    location: msg_payload.scene_name || msg_payload.name || 'Anthem',
                    region:   region_name,
                    object:   'vehicle'
                }
            ];

            node.send({
                payload:     congBody,
                measurement: 'congestion_events',
                timestamp:   timestamp
            });
        }
    } else {
        cState.firstLowSpeedSec = null;
        cState.alertSent = false;
    }
} else {
    cState.firstLowSpeedSec = null;
    cState.alertSent = false;
}

flow.set('congestionTracker', congTracker);

// The analytics service rebuilds objects without image_b64/frame_b64, so keep the
// latest images per global object id from the scene controller output and let the
// event handlers look them up by id.
// Remote child brokers also deliver region data for the reappearance node; only scene output carries images.
if (String(msg.topic).indexOf('scenescape/data/scene/') !== 0) { return null; }
var objects = (msg.payload && msg.payload.objects) || [];
var TTL_MS = 120000;
var now = Date.now();
var cache = flow.get('vehicleImageCache') || {};

objects.forEach(function (o) {
    if (o.id === undefined || (!o.image_b64 && !o.frame_b64)) { return; }
    var rec = cache[o.id] || {};
    if (o.image_b64) { rec.image_b64 = o.image_b64; }
    if (o.frame_b64) { rec.frame_b64 = o.frame_b64; }
    rec.seen = now;
    cache[o.id] = rec;
});

Object.keys(cache).forEach(function (k) {
    if (now - cache[k].seen > TTL_MS) { delete cache[k]; }
});

flow.set('vehicleImageCache', cache);
return null;

// Remote child scenes publish their vehicle images, re-identification results and region
// data on their own broker; the parent controller does not forward them when it merges the
// child objects, so subscribe to each remote child broker directly and feed the same image
// cache and the vehicle reappearance detection.
var total = parseInt(env.get('TOTAL_REMOTE_CHILD') || '0', 10);
var out = [];
for (var i = 1; i <= 2; i++) {
    var ip = (env.get('REMOTE_IP_' + i) || '').trim();
    if (i > total || !ip) { out.push(null); continue; }
    out.push([
        { action: 'connect', broker: { broker: ip, port: 1883 } },
        {
            action: 'subscribe',
            topic: [
                { topic: 'scenescape/data/scene/+/vehicle', qos: 0 },
                { topic: 'scenescape/data/region/+/+/vehicle', qos: 0 },
                { topic: 'scenescape/event/region/+/+/objects', qos: 0 }
            ]
        }
    ]);
}
return out;

// Vehicle Reappearance: a vehicle that the scene controller re-identified (similarity set /
// reid_state 'matched', i.e. matched to a previously seen global UUID) is reported once per visit
// when it is seen in a lane region, but only if that visit started after the vehicle had been
// absent from the intersection for ABSENT_MS or more. A tracker re-linking to a vehicle that is
// still in view stays inside the same visit and is not reported.
// Region data topics only carry the region UUID, so the lane name is learned from the
// scenescape/event/region/<scene>/<region>/objects topic.
var WAIT_MS = 6000;
var ABSENT_MS = 90000;
var WARMUP_MS = 10000;
var VISIT_TTL_MS = 600000;

var parts = (msg.topic || '').split('/');
var payload = msg.payload || {};
var objects = payload.objects || [];
var now = Date.now();
var regionNames = flow.get('reappearanceRegionNames') || {};
var pending = flow.get('reappearancePending') || {};
var visits = flow.get('reappearanceVisits') || {};
var bootAt = flow.get('reappearanceBoot') || now;

function purge(map, field, ttl) {
    Object.keys(map).forEach(function (k) {
        if (now - map[k][field] > ttl) { delete map[k]; }
    });
}

// A visit is a continuous stretch of sightings of one UUID at one intersection. It is a
// reappearance candidate only if it starts after an absence with the vehicle already matched;
// a new vehicle that is matched later within the same visit is not a reappearance.
function touch(sceneUid, o) {
    var k = sceneUid + '|' + o.id;
    var v = visits[k];
    if (!v || now - v.last > ABSENT_MS) {
        var matchedNow = o.reid_state === 'matched' || typeof o.similarity === 'number';
        v = visits[k] = { last: now, reappeared: matchedNow && now - bootAt > WARMUP_MS, reported: false };
    } else {
        v.last = now;
    }
}

if (parts[1] === 'event') {
    if (payload.region_id && payload.region_name) {
        regionNames[payload.region_id] = payload.region_name;
        flow.set('reappearanceRegionNames', regionNames);
    }
    return null;
}
if (parts[1] !== 'data') { return null; }

objects.forEach(function (o) {
    if (o.id !== undefined) { touch(parts[3], o); }
});
purge(visits, 'last', VISIT_TTL_MS);
flow.set('reappearanceVisits', visits);
if (parts[2] !== 'region') { return null; }

var region = regionNames[parts[4]];
if (!region || !/LANE$/.test(region)) { return null; }
var sceneName = String(payload.name || payload.scene_name || 'Anthem');
var safeScene = sceneName.replace(/[^A-Za-z0-9._-]/g, '_');
var fs = global.get('fs');
var imgCache = flow.get('vehicleImageCache') || {};

var ts = new Date(payload.timestamp);
if (isNaN(ts.getTime())) { ts = new Date(); }
var dateStr = ts.toISOString().split('T')[0];
var timeStr = ts.toTimeString().split(' ')[0].replace(/:/g, '');

objects.forEach(function (obj) {
    if (obj.id === undefined) { return; }
    var hasSimilarity = typeof obj.similarity === 'number';
    if (!hasSimilarity && obj.reid_state !== 'matched') { return; }

    var key = parts[3] + '|' + obj.id;
    var visit = visits[key];
    if (!visit || !visit.reappeared || visit.reported) { return; }

    var cached = imgCache[obj.id] || {};
    var imageB64 = obj.image_b64 || cached.image_b64;
    var frameB64 = obj.frame_b64 || cached.frame_b64;

    var rec = pending[key] || (pending[key] = { since: now });
    if (!(imageB64 && frameB64) && now - rec.since < WAIT_MS) { return; }

    delete pending[key];
    visit.reported = true;

    var idSafe = String(obj.id).replace(/[^A-Za-z0-9-]/g, '');
    var baseDir = '/images_data/vehicle-events/' + dateStr + '/' + safeScene;
    var baseUrl = '/images/vehicle-events/' + dateStr + '/' + safeScene;
    var imageUrl = '';
    var frameUrl = '';

    if (imageB64) {
        try {
            fs.mkdirSync(baseDir, { recursive: true });
            var imgName = 'reappear_' + idSafe + '_' + timeStr + '.jpg';
            fs.writeFileSync(baseDir + '/' + imgName, Buffer.from(imageB64, 'base64'));
            imageUrl = baseUrl + '/' + imgName;
        } catch (err) {}
    }
    if (frameB64) {
        try {
            fs.mkdirSync(baseDir, { recursive: true });
            var frameName = 'reappear_frame_' + idSafe + '_' + timeStr + '.jpg';
            fs.writeFileSync(baseDir + '/' + frameName, Buffer.from(frameB64, 'base64'));
            frameUrl = baseUrl + '/' + frameName;
        } catch (err) {}
    }

    var fields = {
        object_id: String(obj.id),
        reappearance: 1,
        event_url: imageUrl,
        frame_url: frameUrl
    };
    if (hasSimilarity) { fields.similarity = parseFloat(obj.similarity.toFixed(3)); }

    node.send({
        payload: [
            fields,
            // vid keeps same-second events of different vehicles in separate series.
            { location: sceneName, region: region, object: 'vehicle', vid: String(obj.id).substring(0, 8) }
        ],
        measurement: 'vehicle_reappearance',
        timestamp: payload.timestamp
    });
});

purge(pending, 'since', WAIT_MS * 5);
flow.set('reappearancePending', pending);
return null;
